#[allow(clippy::too_many_lines)]
fn slice_a() -> Vec<KernelRule> {
    vec![
        // ── A: memory access — a 6..16-row quantized matvec reads each
        // weight block ONCE, dequantizes it in registers, and applies it to
        // every row in the band through a plain simdgroup-mma fragment grid;
        // admission is a PER-SILICON three-tier threshold table with a
        // refuse-loud alignment arm. ──
        KernelRule {
            rule_id: "fewrow-mma-fragment-matvec-silicon-tiered-dispatch".to_string(),
            gpu_concept: "MECHANISM (few-row quantized matvec rides the matrix units through a plain simdgroup-mma fragment grid — NO tensor API; category A — memory access): the few-row matvec ladder's middle rung (B98) has a carrier that needs no cooperative-tensor API and so runs on EVERY Apple generation — a 6..16-row batch keeps the GEMV's per-row output ownership but the weight bytes are READ ONCE, unpacked in registers, and applied to ALL rows through `frag_t C[TN][TM]` mma-fragment accumulators, so the weight traffic is 1x the weight size instead of M x. THE ROUTE, verbatim from the source (quantized.cpp:2218-2223 at c6abf0db): '// For few rows use qmv_mma when N/K is large enough.' + 'if (transpose_ && non_batched && (M >= 6) && (M <= 16) &&' + 'use_qmv_mma(x, w, scales, out, group_size_, bits_, M, N, K, d, s, mode)) {'. THE ADMISSION GATE (`use_qmv_mma`, quantized.cpp:635-666), verbatim: 'if (K % 128 != 0) {' + 'return false;' + '}' + 'if (mode == QuantizationMode::Affine) {' + 'return false;' + '}' + '// Require aligned vector load.' + 'if ((x.offset() % (8 * x.itemsize())) || (w.offset() % 16) ||' + '(scales.offset() % 2)) {' + 'return false;' + '}' — every refusal is LOUD-by-fall-through (the generic matvec serves the shape) and the misaligned-offset refusals are TEST-COVERED: test_qmm_few_rows builds views at odd offsets ('Views at odd offsets must not reach the Metal vector loads' — x offset 1 element via x[1:].reshape, scales offset via a +1 uint8 shift) and asserts CORRECT output through the fallback route, so the refusal is exercised by routing-avoidance, not by an exception. THE PER-SILICON THREE-TIER THRESHOLD TABLE, verbatim: 'if (metal::is_nax_available()) {' + 'return (env::enable_tf32() || x.dtype() != float32) && (N >= 2048) &&' + '(K >= 2048) && (N % 32 == 0);' + '}' + 'if (d.get_architecture().back() == \'d\') {' + 'return (N >= 4096) && (K >= 4096) && (N % 16 == 0);' + '}' + 'return (N >= 512) && (K >= 512) && (int64_t(N) * K >= (int64_t(1) << 22)) &&' + '(N % 16 == 0);' — DRIFT CORRECTION over Research 310's prose: the older tier is FOUR conjuncts, N % 16 == 0 included (the code is authoritative; the research note omitted it). THE READ-ONCE FACE: one `fp_qmv_mma` kernel, BK=128 along K, WK simdgroups stride the K axis ('for (int k = simd_gid * BK; k < K; k += WK * BK)'), each simdgroup's weight block is unpacked in registers (the fp4 embed '((q & 0x00070007) << 9) | ((q & 0x00080008) << 12)' + one 16384.0h bias multiply for gs16; fp_quantized.h:317, :1630, :1646) and consumed by ALL rows in the band; fragment-grid geometry from the host: 'int tm = M > 8 ? 2 : 1;' (TM 1 = 8 rows, TM 2 = 16 rows; 'static_assert(TM == 1 || TM == 2, \'qmv_mma takes at most 16 rows\');' fp_quantized.h:1532), 'int wk = nax || d.get_architecture_gen() >= 15 ? 8 : 4; int bn = nax ? 32 : 16;' (quantized.cpp:680-682); the NAX twin `fp_qmv_nax` (bn=32, wk=8, 'constexpr int BK = 128;' + 'static_assert(BN % 32 == 0, ...)' fp_quantized_nax.h:1091-area) reuses the same tile path on NAX silicon. THE PARTIAL-ROW MASKING face (M = 5/13 legal inside an 8/16-row grid), verbatim (fp_quantized.h:1560-1567): 'bool x_rows[TM][2];' + 'frag_t C[TN][TM];' + 'x_rows[mt][j] = 8 * mt + fn + j < M;' — loads zero-fill past the band ('xs[mt][j][h] = x_rows[mt][j] ? *(const device vec<T, 8>*)(xr + 8 * h) : vec<T, 8>(0);' :1582) and stores gate on the same predicate ('if (x_rows[mt][j]) { device T* yr = y + (8 * mt + fn + j) * static_cast<int64_t>(N) + y_col + fm; ...'), so a 13-row batch runs the full TM=2 grid with rows 13..15 computed-and-discarded — the test band covers it: 'for M in [5, 6, 8, 13, 16, 17]:' (test_quantized.py:803) over 'for N, mode, dtype in product([4128, 4112], modes, dtypes):' (:798; 4128 = N%32==0, 4112 = N%16==0-but-N%32!=0 — the threshold-table paths) at 'K = 4224' (:790). THE EPILOGUE — WK-1 CROSS-SIMDGROUP PARTIAL EXCHANGE, verbatim (fp_quantized.h:1651-1690): 'constexpr int tile_elems = TN * TM * 2;' + 'threadgroup float Ps[(WK - 1) * tile_elems * 32];' + 'if (simd_gid > 0) {' (each non-zero simdgroup publishes its fragment set into its own Ps slot) + 'threadgroup_barrier(mem_flags::mem_threadgroup);' + 'if (simd_gid == 0) {' + 'for (int s = 0; s < WK - 1; s++) {' + 'C[t][mt][j] += p[((t * TM + mt) * 2 + j) * 32];' — simd 0 folds ALL WK-1 partial sets in fixed simd order and alone performs the x_rows-gated stores: every partial crosses exactly one barrier, the fold order is pinned, and no atomics exist. DECISION CONTENT: (a) the M-band route 6..16 with the fall-through posture — outside the band the generic matvec owns the shape, the fast path never stretches; (b) refuse-loud admission BEFORE any threshold: K % 128, affine mode, the three offset alignments (x % 8*itemsize, w % 16, scales % 2) — refusals route to the generic kernel and the test suite pins the misaligned views' CORRECTNESS; (c) the three-tier per-silicon table with per-tier N-alignment (NAX N%32, the other two N%16) — the SAME shape admits at different N/K floors per silicon generation, never one global constant; (d) weight bytes read once, dequant in registers, fragments apply to all rows — the M x weight-traffic collapse; (e) partial-row masking at the fragment predicate (x_rows[TM][2]) with zero-fill loads + gated stores — grid padding is computed, never branched; (f) the WK-1 cross-simdgroup smem exchange epilogue: publish, one barrier, simd 0 folds in simd order. CLASS SIGNATURE: per-silicon three-tier threshold dispatch of a no-tensor-API mma-fragment few-row matvec, fragment-grid partial-row masking, WK-1 cross-simdgroup partial exchange. REGIME: 6..16-row batches over large aligned N/K — speculative/verify bands and small server batches on M1-M5 (the test band M in {5,6,8,13,16,17} pins both edges and the masked middles). ANTI-REGIME: M outside 6..16 (the route falls through by construction); batch 1 and prompt widths (source: 'No observed prompt or batch 1 change' — the incumbent owns them); affine quantization; K % 128 != 0; misaligned buffer offsets; small N/K below the silicon tier's floor. KINSHIP (grep over src/domains/kernel_opt/corpus/, named, BOTH directions): small-batch-matvec-gemm-bridge-rung (gpu_13/B98) owns the LADDER (GEMV / bridge / GEMM rungs, per-type crossover + env-tunable gates) and the middle rung's dequant-amortization in scalar/simdgroup lanes — THIS is one rung's CARRIER and its PER-SILICON admission table (B98's crossover is per-TYPE, never per-silicon thresholds; compose: B98's ladder picks the middle rung, THIS arms it where the silicon thresholds admit); fewrow-tensor-tile-decode-into-rhs-operand (gpu_66/B66 — the LEAGUE PQ2_0 few-row carrier) owns the Metal-4 cooperative-TENSOR-API decode-into-rhs-operand form, M5-class-only — THIS is the no-tensor-API twin that runs plain simdgroup mma on M1-M4 (the carrier is the distinct axis; the weight-block-read-once axis is shared — the same law at a different hardware API); batch-width-routed-dual-tile-twins (gpu_07/B77) owns batch-width routing between two TILE shapes of one GEMM — THIS routes per-silicon THRESHOLD TABLES for a fragment kernel, no tile twins; row-tile-amortize-input-load (gpu_01/B01 — the A-family anchor, with the Batch-108 CMMA staged-GEMM rider: an input tile staged once, consumed across M-subtiles) owns read-once amortization at the tile grain for m >= 64 — THIS is the same economics at the mma-fragment grain for the 6..16-row band where tiles would pad 48 rows to serve 13; mma-fragment-layout-m16n8k16 (gpu_09) owns the fragment LAYOUT contract the grid consumes; apple10-narrow-grid-register-tile-threadgroups-per-core (gpu_117/B268) owns per-decode-step VARIANT selection by tg/core occupancy on the newer family — THIS admits by per-silicon N/K floors, never occupancy. GREP EVIDENCE: 'fewrow|few-row' -> fewrow-tensor-tile-decode-into-rhs-operand (gpu_66), small-batch-matvec-gemm-bridge-rung (gpu_13) — the axis's owners, neither carries the no-tensor-API fragment carrier nor the silicon table; 'fragment' -> mma-fragment-layout-m16n8k16 (gpu_09 — layout), j16-warp-fragment-direct-no-smem-tile (gpu_106 — the no-reuse anti-pole); 'qmv' -> zero owners; 'silicon-tier|per-silicon' -> zero owners of a three-tier threshold dispatch. NotBenchable here (Metal mma-fragment kernels on Apple silicon; the corpus serves no Metal validator; the NAX tier does not fire on the boxes this corpus serves — M3 Max has no NAX, the 4090 is not Metal — the entries_gpu_65 standing disclosure; decision content verifiable by inspection). MEASURED (source-reported, M5 Max, mlx_lm.benchmark, PR body — provenance, never our bar): Qwen3.8-27B-nvfp4 batch 8 113.1 -> 187.9 tok/s (1.66x), batch 16 149.5 -> 298.4 tok/s (2.00x), mxfp4 2.10x, mxfp8 1.72x; batch 1 and prompt UNCHANGED ('No observed prompt or batch 1 change'); '~3x on M1/M2' is THEIR claim — the M1-M4 arm is unverified here (no such silicon on the corpus boxes). Source: ml-explore/mlx @ c6abf0db (Metal: Add qmv_mma/qmv_nax kernels for 6-16 rows with large N/K #4712), MIT -- mlx/backend/metal/quantized.cpp + kernels/fp_quantized.h + kernels/fp_quantized_nax.h. Batch 273 / Plan 277 / Research 310. Every quote verbatim at the pin. BATCH-337 FACE (jitengine qmv_mrow, Plan 346 / Research 376 -- the multi-row-share-weight-read candidate adjudicated TO THIS HOST): the dense multi-row weight-share carries a WEIGHT-SIZE admission key -- SOLO_MIN_BYTES = 64 MiB ('smallest weight for which one call's saving beats the wrapper cost') -- plus per-shape calibration (calibrate_solo / calibrate_mrow; 2-row blocks where rl4 is off, MROW_BLOCK = 2) and the verify-window posture ('a verify window or a batch matches one-row decoding at any row count', bit-identical, README-contract-pinned) -- the admission axis composes with this host's row-band mechanism; the mechanism itself (weight bytes read once, applied to all rows) stays owned here.".to_string(),
            ref_shape: "// ref_shape: a few-row (6..16) quantized matvec written as N independent\n// row-dots — every row's pass re-reads and re-decodes the SAME weight\n// bytes, so the weight traffic is M x the weight size no matter how few\n// the rows are. The dispatch asks nothing about the silicon.\n#![allow(dead_code)]\n\nconst BLOCK: usize = 32; // weights per quant block\nconst CODES_PER_BYTE: usize = 4; // 2-bit codes per byte (stand-in for fp4)\n\nfn dequant_byte(b: u8, i: usize) -> i32 {\n    (i64::from((b >> ((i % CODES_PER_BYTE) * 2)) & 3) - 1) as i32\n}\n\nfn weight_reads_naive(rows: usize, bytes: usize) -> usize {\n    rows * bytes // every row re-reads every weight byte\n}\n\n// naive: one dot per OUTPUT ROW; the weight loop runs once PER ROW\nfn fewrow_naive(w_packed: &[u8], scales: &[i32], x: &[i32], m: usize) -> Vec<i32> {\n    let n_blocks = w_packed.len() / BLOCK;\n    (0..m)\n        .map(|_| {\n            let mut acc = 0i32;\n            for blk in 0..n_blocks {\n                for i in 0..BLOCK {\n                    let w = dequant_byte(w_packed[blk * BLOCK + i], i) * scales[blk];\n                    acc += w * x[blk * BLOCK + i];\n                }\n            }\n            acc\n        })\n        .collect()\n}\n\n#[test]\nfn the_naive_path_re_reads_the_weights_per_row() {\n    let w: Vec<u8> = (0..64).map(|i| (i * 37 + 11) as u8).collect();\n    let scales = [2i32; 2];\n    let x: Vec<i32> = (0..64).map(|k| (k % 7) as i32 - 3).collect();\n    let out = fewrow_naive(&w, &scales, &x, 13);\n    assert_eq!(out.len(), 13);\n    // 13 rows x 64 weight bytes: the traffic is M x the weight size\n    assert_eq!(weight_reads_naive(13, w.len()), 13 * 64);\n    // and every row computed the SAME dot against the same weights\n    let solo = fewrow_naive(&w, &scales, &x, 1);\n    assert!(out.iter().all(|o| *o == solo[0]));\n}".to_string(),
            opt_pattern: "// opt_pattern: the band (6..16 rows) reads every weight block ONCE into\n// registers, dequantizes it there, and applies it to ALL rows through a\n// TM x 2 row-fragment grid; the x_rows[TM][2] predicate masks the partial\n// rows (zero contribution, gated stores — an M=13 batch runs the TM=2\n// grid with rows 13..15 computed-and-discarded); the host dispatch is the\n// per-silicon THREE-TIER threshold table with the refuse-loud alignment\n// arm. The WK-1 cross-simdgroup partial exchange is modeled as the\n// per-simdgroup partial sets folded in fixed simd order at the end.\n#![allow(dead_code)]\n\nconst BLOCK: usize = 32;\nconst CODES_PER_BYTE: usize = 4;\n\nfn dequant_byte(b: u8, i: usize) -> i32 {\n    (i64::from((b >> ((i % CODES_PER_BYTE) * 2)) & 3) - 1) as i32\n}\n\n// ── the per-silicon three-tier threshold table (use_qmv_mma's tail) ──\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Silicon {\n    Nax,\n    ArchD, // the architecture string ends in 'd' (the M3-class tier)\n    Older,\n}\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\nenum Route {\n    NaxTier,\n    M3ClassTier,\n    OlderTier,\n    Refuse,\n}\n\nfn route(silicon: Silicon, n: u64, k: u64) -> Route {\n    match silicon {\n        // 'if (metal::is_nax_available()) { return ... (N >= 2048) &&\n        //  (K >= 2048) && (N % 32 == 0); }'\n        Silicon::Nax if n >= 2048 && k >= 2048 && n % 32 == 0 => Route::NaxTier,\n        // 'if (d.get_architecture().back() == 'd') { return (N >= 4096) &&\n        //  (K >= 4096) && (N % 16 == 0); }'\n        Silicon::ArchD if n >= 4096 && k >= 4096 && n % 16 == 0 => Route::M3ClassTier,\n        // the older tier is FOUR conjuncts — N % 16 == 0 included (the\n        // slice-A drift correction over the research prose).\n        Silicon::Older\n            if n >= 512 && k >= 512 && n * k >= (1u64 << 22) && n % 16 == 0 =>\n        {\n            Route::OlderTier\n        }\n        _ => Route::Refuse,\n    }\n}\n\n// ── the refuse-loud alignment arm (the gate BEFORE the table) ──\nfn alignment_ok(x_off: usize, w_off: usize, s_off: usize, itemsize: usize) -> bool {\n    // '(x.offset() % (8 * x.itemsize())) || (w.offset() % 16) ||\n    //  (scales.offset() % 2)'\n    x_off % (8 * itemsize) == 0 && w_off % 16 == 0 && s_off % 2 == 0\n}\n\n// ── the M-band route (quantized.cpp:2218-2223) ──\nfn in_band(m: usize) -> bool {\n    (6..=16).contains(&m)\n}\n\n// ── the fragment grid: weight block read ONCE, applied to all rows ──\nconst TM: usize = 2; // 'static_assert(TM == 1 || TM == 2, ...)'\nconst FRAG_ROWS: usize = 8; // rows per TM step: 8*mt + j\n\n// 'x_rows[mt][j] = 8 * mt + fn + j < M;' — the partial-row predicate\nfn x_rows(mt: usize, j: usize, m: usize) -> bool {\n    FRAG_ROWS * mt + j < m\n}\n\nfn weight_reads_fragments(bytes: usize) -> usize {\n    bytes // the weight bytes are read ONCE for the whole band\n}\n\nfn fewrow_fragments(w_packed: &[u8], scales: &[i32], x: &[i32], m: usize) -> Vec<i32> {\n    debug_assert!(in_band(m), \"qmv_mma takes at most 16 rows; band is 6..16\");\n    let n_blocks = w_packed.len() / BLOCK;\n    let mut out = vec![0i32; m];\n    for blk in 0..n_blocks {\n        // the block's bytes cross the register grid ONCE...\n        let mut frag_dots = [0i32; TM * FRAG_ROWS]; // one dot per logical row\n        for i in 0..BLOCK {\n            let w = dequant_byte(w_packed[blk * BLOCK + i], i) * scales[blk];\n            let xv = x[blk * BLOCK + i];\n            // ...and apply to EVERY fragment row; the x_rows predicate\n            // makes masked rows zero-contribution (the zero-fill load arm)\n            for frag_row in 0..TM * FRAG_ROWS {\n                if x_rows(frag_row / FRAG_ROWS, frag_row % FRAG_ROWS, m) {\n                    frag_dots[frag_row] += w * xv;\n                }\n            }\n        }\n        // the gated-store arm: only in-band rows reach the output\n        for (r, d) in frag_dots.iter().enumerate() {\n            if r < m {\n                out[r] += *d;\n            }\n        }\n    }\n    out\n}\n\n#[test]\nfn the_three_tier_table_admits_per_silicon() {\n    // NAX tier: N,K >= 2048 AND N % 32 == 0\n    assert_eq!(route(Silicon::Nax, 2048, 2048), Route::NaxTier);\n    assert_eq!(route(Silicon::Nax, 2048, 1024), Route::Refuse); // K floor\n    assert_eq!(route(Silicon::Nax, 2064, 2048), Route::Refuse); // N % 32\n    // M3-class tier: N,K >= 4096 AND N % 16 == 0\n    assert_eq!(route(Silicon::ArchD, 4096, 4096), Route::M3ClassTier);\n    assert_eq!(route(Silicon::ArchD, 4100, 4096), Route::Refuse); // N % 16\n    assert_eq!(route(Silicon::ArchD, 4096, 2048), Route::Refuse);\n    // the same shape the NAX tier refused (N % 32 != 0) admits here\n    assert_eq!(route(Silicon::ArchD, 4112, 4096), Route::M3ClassTier);\n}\n\n#[test]\nfn the_older_tier_requires_all_four_conjuncts() {\n    // exactly at the 2^22 product floor: 512 * 8192 = 2^22\n    assert_eq!(route(Silicon::Older, 512, 8192), Route::OlderTier);\n    // one below the product floor: 512 * 8190 < 2^22\n    assert_eq!(route(Silicon::Older, 512, 8190), Route::Refuse);\n    // N % 16 refused even with a huge product (the drift-corrected arm)\n    assert_eq!(route(Silicon::Older, 520, 16_384), Route::Refuse);\n    // and the test band's own N: 4112 admits on N % 16 alone\n    assert_eq!(route(Silicon::Older, 4112, 4224), Route::OlderTier);\n    assert_eq!(route(Silicon::Older, 512, 512), Route::Refuse); // product\n}\n\n#[test]\nfn the_band_and_alignment_gates_refuse_loud() {\n    // the M-band: 6..16 only (quantized.cpp:2218-2223)\n    assert!(!in_band(5));\n    assert!(in_band(6));\n    assert!(in_band(13));\n    assert!(in_band(16));\n    assert!(!in_band(17));\n    // the alignment arm: x % 8*itemsize, w % 16, scales % 2\n    assert!(alignment_ok(0, 0, 0, 2));\n    assert!(!alignment_ok(1 * 2, 0, 0, 2)); // x off by one element\n    assert!(!alignment_ok(0, 8, 0, 2)); // w off by 8 bytes\n    assert!(!alignment_ok(0, 0, 1, 2)); // scales off by one byte\n}\n\n#[test]\nfn the_fragments_match_the_naive_rows_and_read_once() {\n    let w: Vec<u8> = (0..64).map(|i| (i * 37 + 11) as u8).collect();\n    let scales = [2i32; 2];\n    let x: Vec<i32> = (0..64).map(|k| (k % 7) as i32 - 3).collect();\n    // M = 13: a PARTIAL TM=2 grid (rows 13..15 masked) — the in-band rows\n    // must equal the naive row-dots bit for bit\n    let got = fewrow_fragments(&w, &scales, &x, 13);\n    let want = (0..13)\n        .map(|_| {\n            (0..w.len() / BLOCK)\n                .map(|blk| {\n                    (0..BLOCK)\n                        .map(|i| {\n                            dequant_byte(w[blk * BLOCK + i], i) * scales[blk]\n                                * x[blk * BLOCK + i]\n                        })\n                        .sum::<i32>()\n                })\n                .sum::<i32>()\n        })\n        .collect::<Vec<_>>();\n    assert_eq!(got, want);\n    // the economics: 64 bytes read once for the band, not 13 x 64\n    assert_eq!(weight_reads_fragments(w.len()), 64);\n}".to_string(),
        },
    ]
}

pub fn entries() -> Vec<KernelRule> {
    let v = slice_a();
    debug_assert_eq!(v.len(), 1, "batch 273: 1 own kernel_opt rule");
    v
}
